from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def max_nesting_depth(group: str) -> int:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        return max_depth

    groups = paren_string.split()
    result = []
    for group in groups:
        result.append(max_nesting_depth(group))

    return result

